    assert result == expected


@pytest.mark.parametrize(
    "a, b, expected",
    [
        (-1, 2, 18),   # -1 % 10 == 9 in Python
        (1, -2, 8),    # -2 % 10 == 8
        (-3, -4, 42),  # 7 * 6
    ],
)
def test_multiply_negative_numbers(a, b, expected):
    result = multiply(a, b)
    assert result == expected


def test_multiply_zero():
    result = multiply(0, 5)
    assert result == 0
